# region: digest
def digest(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: shape
def shape(xs):
    return [v for v in xs if v % 2 == 0]

# region: render
def render(xs, limit=5):
    return [v if v <= limit else limit for v in xs[1:]]

# region: gather
def gather(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: sift
def sift(summary, bar=2):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return sift(gather(render(shape(digest(raw)))))

